/**
 * User API
 * 用戶管理相關 API
 */

(function() {
    const API = window.DMSAPI;
    if (!API) {
        console.error('DMSAPI not initialized. Please include api/index.js first.');
        return;
    }

    // Mock user data
    const mockUserData = {
        detailInfo: {
            id: '6e01b808-6841-11f0-94bb-5254008c2c02',
            username: 'admin',
            roleId: 'fb509ca6-7bf0-11ea-b5b2-0a002700000e',
            roleName: '管理員',
            phone: '15862589286',
            email: '666@qq.com',
            createTime: '2025-07-24'
        }
    };

    window.UserAPI = {
        /**
         * 取得用戶列表
         * @param {Object} params - { keyword, pageNum, limit }
         * @returns {Promise}
         */
        getUserList: async function(params) {
            return API.get('/schideron/openApi/user/list', {
                ...params,
                requester: API.requester
            });
        },

        /**
         * 取得用戶詳細資料
         * @param {string} userId - 用戶 ID
         * @returns {Promise}
         */
        getProfile: async function(userId) {
            try {
                const response = await API.get(
                    `/schideron/openApi/user/detail/${userId}`,
                    { requester: API.requester }
                );
                console.log('getProfile', response);
                return {
                    result: 'success',
                    data: response
                };
            } catch (error) {
                console.warn('Backend API unavailable, using mock data:', error);
                return {
                    result: 'success',
                    data: mockUserData
                };
            }
        },

        /**
         * 更新密碼
         * @param {Object} payload - { id, newPassword }
         * @returns {Promise}
         */
        updatePassword: async function(payload) {
            return API.post(`/schideron/openApi/user/resetPassword/${payload.id}`, {
                defaultPassword: payload.newPassword,
                requester: API.requester
            });
        },

        /**
         * 更新用戶資料
         * @param {Object} payload - { id, username, roleId, phone, email }
         * @returns {Promise}
         */
        updateUser: async function(payload) {
            return API.put(`/schideron/openApi/user/edit/${payload.id}`, {
                requester: API.requester,
                username: payload.username,
                roleId: payload.roleId,
                phone: payload.phone,
                email: payload.email
            });
        },

        /**
         * 刪除用戶
         * @param {Object} payload - { id }
         * @returns {Promise}
         */
        deleteUser: async function(payload) {
            return API.delete(`/schideron/openApi/user/delete/${payload.id}`, {
                requester: API.requester
            });
        },

        /**
         * 新增用戶
         * @param {Object} payload - { username, roleId, phone, email, password }
         * @returns {Promise}
         */
        addUser: async function(payload) {
            return API.post('/schideron/openApi/user/add', {
                requester: API.requester,
                ...payload
            });
        }
    };

    console.log('User API initialized');
})();
